function popAll(values) {
  const stack = [];                  // a JavaScript array is the stack
  for (const x of values) stack.push(x);
  const out = [];
  while (stack.length > 0) {         // check before popping
    out.push(stack.pop());
  }
  return out;                        // [1, 2, 3] -> [3, 2, 1]
}

List<Integer> popAll(int[] values) {
    Deque<Integer> stack = new ArrayDeque<>();   // Java's recommended stack
    for (int x : values) stack.push(x);
    List<Integer> out = new ArrayList<>();
    while (!stack.isEmpty()) {
        out.add(stack.pop());
    }
    return out;                                  // [1, 2, 3] -> [3, 2, 1]
}

vector<int> popAll(const vector<int>& values) {
    stack<int> st;
    for (int x : values) st.push(x);
    vector<int> out;
    while (!st.empty()) {
        out.push_back(st.top());     // read the top first...
        st.pop();                    // ...because pop() returns nothing
    }
    return out;                      // [1, 2, 3] -> [3, 2, 1]
}

class LinkedStack {
  constructor() {
    this.head = null;        // the top of the stack
    this.count = 0;
  }
  push(x) {
    const node = new ListNode(x);
    node.next = this.head;   // the new node points at the old top
    this.head = node;        // and becomes the new top
    this.count++;
  }
  pop() {
    if (this.head === null) return null;   // underflow
    const x = this.head.val;
    this.head = this.head.next;            // the old top falls away
    this.count--;
    return x;
  }
  peek() {
    return this.head === null ? null : this.head.val;
  }
}

