class LinkedStack {
    ListNode* head = nullptr;    // the top of the stack
    int count = 0;

public:
    void push(int x) {
        ListNode* node = new ListNode(x);
        node->next = head;       // the new node points at the old top
        head = node;             // and becomes the new top
        count++;
    }

    int pop() {
        if (head == nullptr) throw out_of_range("pop from an empty stack");   // underflow
        ListNode* old = head;
        int x = old->val;
        head = head->next;       // the old top falls away
        delete old;              // C++ has no garbage collector
        count--;
        return x;
    }

    int peek() {
        if (head == nullptr) throw out_of_range("peek at an empty stack");
        return head->val;
    }
};
